  ('340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$Biologie$$, $$HAVO$$, $$Een nieuwe groente: eendenkroos$$, $$HAVO Biologie 2025-I$$),
  ('ecb62a3b-d239-400a-b348-17962cae8ff5', $$Biologie$$, $$HAVO$$, $$De Bajau$$, $$HAVO Biologie 2025-I$$),
