insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('34f93781-57f9-440d-b844-8de75269928f', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$inleiding: boswachter in Nationaal Park De Biesbosch$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context1.png$$,
   $$Thomas van der Es werkt als boswachter voor Staatsbosbeheer in Nationaal Park De Biesbosch. In dit gebied zet hij zich in voor het behoud van de biodiversiteit.$$, 'inline'),
  ('aded51ce-c123-41e0-b8c4-9e25e5494f7d', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$kader: zeearenden in De Biesbosch en in Nederland (afbeelding 1 en 2)$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context2.png$$,
   $$De Biesbosch is een waterrijk natuurgebied met veel wilgenbossen. Sinds 2006 broeden er zeearenden (afbeelding 1). Vanaf 1990 nam de populatie zeearenden in Duitsland toe door een afname van het gebruik van bepaalde insecticiden en door een jachtverbod.
Zeearenden werden al eerder in Nederland waargenomen, maar pas vanaf 2006 vestigden ze zich. Dat kon doordat er steeds meer natte natuurgebieden ontstonden, waar vogels die prooi zijn voor de zeearend, in grote groepen aanwezig zijn. Afbeelding 2 toont de plaatsen waar nu zeearenden broeden in Nederland.
afbeelding 1: foto van een zeearend
afbeelding 2: kaart van Nederland met broedplaatsen van zeearenden, onder andere bij de Oostvaardersplassen en de Biesbosch$$, 'inline'),
  ('c3e4dc93-0905-4f0b-a6dc-251ecb7a67f0', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$de zeearend is in Nederland geen exoot$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context3.png$$,
   $$De zeearend is in Nederland geen exoot.$$, 'inline'),
  ('b7ee4504-a1fd-45a5-b5fc-c2767aed40d6', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$insecticiden bedreigen toppredatoren$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context4.png$$,
   $$Insecticiden worden in de landbouw gebruikt om insecten te doden die voedselgewassen aantasten. Bepaalde insecticiden (zoals het verboden middel DDT) zijn een grote bedreiging voor de gezondheid van toppredatoren zoals de zeearend. Voor vogels die insecten eten, vormen deze insecticiden een minder groot gevaar, ondanks dat deze vogels even gevoelig zijn voor het gif als zeearenden.$$, 'inline'),
  ('7e13c4ef-8066-4d95-a331-f34ba389dfbb', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$afbeelding 3: aantal broedparen van de zeearend in Nederland$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context5.png$$,
   $$Afbeelding 3 toont het aantal broedparen van de zeearend in Nederland tot en met 2021.
afbeelding 3: staafdiagram aantal broedparen per jaar (2000-2021): 0 tot en met 2005; 1 in 2006, 2007 en 2008; 2 in 2009; 3 in 2010 en 2011; 4 in 2012; 5 in 2013 en 2014; 6 in 2015; 9 in 2016; 12 in 2017; 14 in 2018; 15 in 2019; 20 in 2020; 22 in 2021$$, 'inline'),
  ('d5a86d89-18af-42f8-8d2c-c73556eb7116', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$drie uitspraken over afbeelding 3$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context6.png$$,
   $$Hieronder staan uitspraken over deze gegevens.
1 In 2006 werd in totaal één zeearend waargenomen.
2 Tussen 2006 en 2015 was de groei van het aantal broedende zeearenden in Nederland exponentieel.
3 In 2010 werden er geen kuikens grootgebracht.$$, 'inline'),
  ('f80a2ad0-b8f9-4f9d-a62d-58f330ea025a', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$kader: ringen van jonge zeearenden$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context7.png$$,
   $$Als er jonge zeearenden uit het ei zijn gekomen, helpt Van der Es met het ringen van de jongen. Die krijgen een ring met een unieke code om hun poot. Zo kunnen onderzoekers inzicht krijgen in paarvorming en migratie van deze vogels. Nederlandse zeearenden blijken bijvoorbeeld ook paartjes te vormen met Duitse zeearenden, en ook met niet-geringde zeearenden waarvan de herkomst onbekend is.$$, 'inline'),
  ('85190898-85a6-4ada-ac17-98492364ec94', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$paarvorming met zeearenden uit andere gebieden$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context8.png$$,
   $$Voor het voortbestaan van een populatie zeearenden is paarvorming met zeearenden uit andere gebieden van belang.$$, 'inline'),
  ('76428a3d-c3af-445b-bbed-334e15e0e9f6', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$broedsucces en abiotische factoren$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context9.png$$,
   $$De broedpogingen van de zeearend zijn niet altijd succesvol: er vliegen dan geen kuikens uit. Soms komt dit door menselijke activiteiten, zoals bij verstoring door het filmen van het nest. In andere gevallen zijn abiotische factoren verantwoordelijk voor een lager broedsucces.$$, 'inline'),
  ('61770e7b-f27c-4c61-8b4b-288166212116', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$kader: twee methodes voor geslachtsbepaling$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context10.png$$,
   $$Bij het ringen wordt het geslacht van de jonge zeearend bepaald. De geslachtsorganen zijn niet uiterlijk zichtbaar. Er zijn wel andere meetbare uiterlijke kenmerken die verschillend zijn bij vrouwtjes en mannetjes. Er zijn twee methodes die eenvoudig in het veld gebruikt kunnen worden. Methode 1: onderzoekers meten de breedte en dikte van een bepaald bot in de poot. Deze twee gegevens worden met elkaar vermenigvuldigd. Methode 2: onderzoekers bepalen het gewicht en de vleugellengte.$$, 'inline'),
  ('19d5924b-4f2b-4bdb-b07a-4d452bf35d08', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$controle van het geslacht met een huidmonster$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context11.png$$,
   $$Bij het testen van deze methodes moest ter controle ook het geslacht van elke gemeten zeearend met zekerheid worden vastgesteld. Dit werd gedaan aan de hand van een huidmonster.$$, 'inline'),
  ('5dbc3319-132a-45ad-a1d8-8992589d897a', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$meetgegevens van methode 1 en 2$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context12.png$$,
   $$De meetgegevens van methode 1 en 2 staan in afbeelding 4. Elk bolletje in deze diagrammen is een bepaling bij één zeearend.$$, 'inline'),
  ('370ccfc8-08df-4811-865b-f330c649d5b9', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$afbeelding 4: diagrammen van methode 1 en methode 2$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context13.png$$,
   $$afbeelding 4: methode 1: breedte × dikte bot (mm²) bij vrouwtjes ongeveer 243-282, bij mannetjes ongeveer 198-230; methode 2: gewicht (kg) uitgezet tegen vleugellengte (mm), de punten van vrouwtjes en mannetjes overlappen grotendeels
Uit de diagrammen blijkt welke methode het meest geschikt is voor geslachtsbepaling.$$, 'inline'),
  ('01842a16-db25-497a-944a-dcab5b327495', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$kader: bevers en zwarte populieren (afbeelding 5)$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context14.png$$,
   $$Tussen 1988 en 1991 werden 41 bevers in De Biesbosch uitgezet. De populatie is gegroeid tot ruim 300 dieren. Bevers (afbeelding 5) knagen met hun scherpe tanden bomen om, zoals zwarte populieren, zodat ze van de jonge takken kunnen eten. Zeearenden gebruiken zwarte populieren om hun nest in te maken, omdat deze boomsoort stevige takken heeft.
afbeelding 5: foto van een bever die aan een boomstam knaagt$$, 'inline'),
  ('3e597fae-7e48-44b7-9254-edaf0a1caec0', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$kippengaas rond nestbomen: keuze voor de zeearend$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context15.png$$,
   $$Van der Es bekleedt de stammen van potentiële nestbomen met kippengaas om te verhinderen dat bevers ze omknagen. Hij krijgt hier regelmatig vragen over. Bevers en zeearenden zijn namelijk beide beschermde diersoorten. Van der Es vindt dat in dit geval de keuze voor de zeearend het best is.$$, 'inline'),
  ('d58321e7-bc63-4812-b778-2e7dba36fba6', 'b03e3dc0-38e3-4977-bc2a-b9da1dfc7cb5', $$stelling: commensalisme tussen zwarte populier en zeearend$$,
   $$biologie-havo-2025-i-de-zeearend-moet-blijven-context16.png$$,
   $$De relatie tussen de zwarte populier en de zeearend kan commensalisme genoemd worden.$$, 'inline'),
  ('bd8c81ff-833f-4d3a-a234-153f6d038f44', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$inleiding: Eileen heeft Fanconi-anemie$$,
   $$biologie-havo-2025-i-fanconi-anemie-context1.png$$,
   $$Toen Eileen zes jaar oud was, kreeg ze last van extreme vermoeidheid, infecties en bloedingen. Ze bleek Fanconi-anemie te hebben.$$, 'inline'),
  ('ed4ef9b2-0a0f-4cfd-9985-a477bdedb851', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$kader: overerving van Fanconi-anemie en stamboom (afbeelding 1)$$,
   $$biologie-havo-2025-i-fanconi-anemie-context2.png$$,
   $$Fanconi-anemie (FA) is een zeldzame erfelijke ziekte waarbij er onder andere een verminderde aanmaak is van de vaste bloedbestanddelen. FA wordt meestal veroorzaakt door een mutatie die aanwezig is in een autosomaal gen, het FANCA-gen. Het mutante allel is recessief. Normaal gesproken regelt het FANCA-gen dat DNA gerepareerd kan worden. Fanconi-anemie kan ook ontstaan door een mutatie die aanwezig is in een gen op het X-chromosoom. Ook dit mutante allel is recessief. Bij Eileen is FA het gevolg van autosomale overerving. In afbeelding 1 staat de stamboom van de familie van Eileen.
afbeelding 1: stamboom: twee grootouderparen (man en vrouw zonder FA); de dochter van het linker paar (moeder, zonder FA) en een zoon van het rechter paar (vader, zonder FA) hebben drie kinderen: een zoon zonder FA, Eileen (vrouw met FA) en een dochter zonder FA; de vader heeft nog een broer zonder FA$$, 'inline'),
  ('3a65d8e0-fa26-4b30-bf44-fe834463b642', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$afbeelding 2: microscopisch preparaat van gezond bloed$$,
   $$biologie-havo-2025-i-fanconi-anemie-context3.png$$,
   $$Door de erfelijke aandoening heeft Eileen te weinig vaste bloedbestanddelen. Daardoor is ze altijd moe en heeft ze vaak last van infecties en bloedingen. Afbeelding 2 is een microscopisch preparaat van gezond bloed. Hierin zijn verschillende vaste bloedbestanddelen met nummers aangegeven.
afbeelding 2: microscopisch preparaat van bloed met de nummers 1, 2 en 3 bij verschillende vaste bloedbestanddelen$$, 'inline'),
  ('64efa0a2-56d7-4c64-a55d-4c904b4de23a', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$op de uitwerkbijlage staat een tabel$$,
   $$biologie-havo-2025-i-fanconi-anemie-context4.png$$,
   $$Op de uitwerkbijlage staat een tabel.$$, 'inline'),
  ('3725e132-d44e-4aed-8e0c-953dda72b9c6', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$kader: bloedtransfusie en bloedgroepen$$,
   $$biologie-havo-2025-i-fanconi-anemie-context5.png$$,
   $$In het eerste jaar na de diagnose krijgt Eileen om de paar weken een bloedtransfusie met bloedplaatjes en rode bloedcellen. De toegediende rode bloedcellen zijn bij voorkeur van Eileens eigen bloedgroep. Eileen heeft bloedgroep B en is resuspositief (B+). In noodgevallen zou ze ook rode bloedcellen van andere bloedgroepen kunnen ontvangen. Het ziekenhuis heeft de volgende andere rode bloedcellen op voorraad: A+, A–, B–, AB+, AB–, 0+ en 0–.$$, 'inline'),
  ('7415ab5c-7331-4cc4-a3c8-404363826f90', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$kader: stamceltransplantatie na chemotherapie$$,
   $$biologie-havo-2025-i-fanconi-anemie-context6.png$$,
   $$Eileen komt in aanmerking voor een stamceltransplantatie. Eerst ondergaat ze chemotherapie om haar eigen bloedstamcellen te vernietigen. Enkele dagen later krijgt ze gezonde stamcellen van een donor.$$, 'inline'),
  ('f6c6d148-3b51-485e-a247-42aaddb628f0', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$katheter in een bloedvat (afbeelding 3)$$,
   $$biologie-havo-2025-i-fanconi-anemie-context7.png$$,
   $$Om de bloedstamcellen toe te dienen, wordt bij Eileen een slangetje (katheter) door de huid in een bloedvat aangebracht (afbeelding 3).$$, 'inline'),
  ('2371c632-d74a-4570-a476-18f2312f1a89', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$afbeelding 3: katheter in de borstkas$$,
   $$biologie-havo-2025-i-fanconi-anemie-context8.png$$,
   $$afbeelding 3: tekening van de borstkas met het hart en de grote bloedvaten, met een katheter die door de huid in een bloedvat is aangebracht$$, 'inline'),
  ('b067e4c5-9664-403f-b0ed-f36765b0ee9d', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$de katheter mondt uit bij het hart$$,
   $$biologie-havo-2025-i-fanconi-anemie-context9.png$$,
   $$De katheter mondt uit in een bloedvat in de buurt van het hart.$$, 'inline'),
  ('3e227d2e-89f0-4748-a1f0-4f40ff4caa35', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$uit stamcellen ontstaan typen bloedcellen$$,
   $$biologie-havo-2025-i-fanconi-anemie-context10.png$$,
   $$In de weken na de stamceltransplantatie zullen uit de gedoneerde stamcellen verschillende typen bloedcellen ontstaan die Eileen nodig heeft.$$, 'inline'),
  ('0532e6ff-07a4-47ed-9e05-4ab93788cd3b', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$omgekeerde afstotingsziekte$$,
   $$biologie-havo-2025-i-fanconi-anemie-context11.png$$,
   $$Een gevaar bij stamceltransplantatie is de omgekeerde afstotingsziekte. Die treedt op als de afweercellen die uit de gedoneerde cellen ontstaan, de cellen van Eileen aanvallen en lekprikken. Om dit tegen te gaan is een donor gezocht van wie de membraaneiwitten op de lichaamscellen zo veel mogelijk overeenkomen met die van Eileen.$$, 'inline'),
  ('6757abbc-5dae-4124-8cf6-ba56e08ce1e8', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$vestiging van de gedoneerde stamcellen$$,
   $$biologie-havo-2025-i-fanconi-anemie-context12.png$$,
   $$De stamceltransplantatie is geslaagd als de gedoneerde stamcellen zich vestigen op de plaats waar ook bij gezonde mensen bloedcellen ontstaan.$$, 'inline'),
  ('dc4e1fa1-2987-4ac2-9e79-2b908c726973', '69791ee3-356c-4e64-9d6e-33d38e54feb6', $$uitwerkbijlage vraag 12: tabel bloedbestanddelen$$,
   $$biologie-havo-2025-i-fanconi-anemie-context13.png$$,
   $$12
uitwerkbijlage: tabel met kolommen bloedbestanddeel / nummer in afbeelding 2 / symptoom bij tekort en rijen bloedplaatje, rode bloedcel, witte bloedcel$$, 'uitwerkbijlage'),
  ('34d1eaee-e117-41c9-a82a-2bb21fd8f72c', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$inleiding: eendenkroos als eiwitrijke groente$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context1.png$$,
   $$Ingrid van der Meer van Wageningen University & Research onderzoekt de mogelijkheid om eendenkroosplantjes te gebruiken als eiwitrijke groente.$$, 'inline'),
  ('6b9d6c2c-3021-4c3e-bf6e-278adf115d61', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$kader: eendenkroos, huidmondjes en wortels (afbeelding 1 en 2)$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context2.png$$,
   $$Eendenkroos is een verzamelnaam voor verschillende soorten drijvende waterplantjes van enkele millimeters groot, zoals Lemna minor (afbeelding 1). De plantjes bestaan uit een bladachtig schijfje dat op het water drijft. De huidmondjes bevinden zich aan de bovenzijde van de blaadjes en staan altijd open. Bij sommige eendenkroossoorten zijn wortels aanwezig (afbeelding 2).
afbeelding 1: foto van eendenkroos op het water
afbeelding 2: tekening van eendenkroosplantjes met wortels$$, 'inline'),
  ('503f07fc-e073-4bd9-906a-846c01798370', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$functie van huidmondjes$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context3.png$$,
   $$De functie van huidmondjes is de opname en afgifte van gassen.$$, 'inline'),
  ('bc48717d-9769-4369-88ad-362025a715ad', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$voortplanting van eendenkroos; drie kenmerken$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context4.png$$,
   $$Eendenkroos kan zich zowel geslachtelijk als ongeslachtelijk voortplanten. In het voorjaar worden soms bloemetjes gevormd, maar meestal plant eendenkroos zich voort door nieuwe bladschijfjes af te splitsen. Hieronder staan kenmerken van voortplanting.
1 Er treedt meiose op.
2 De nakomelingen zijn genetisch identiek aan de ouders.
3 Recombinatie van de chromosomen is mogelijk.$$, 'inline'),
  ('84a49213-e241-4c65-bb8d-71bed2161876', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$zuurstoftekort door eendenkroos; vier gebeurtenissen$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context5.png$$,
   $$Eendenkroos groeit op ondiep, stilstaand of langzaam stromend water in sloten en vijvers. In de periode van mei tot oktober groeit de populatie snel. Als het wateroppervlak geheel met eendenkroos bedekt is, kan een tekort aan zuurstof ontstaan voor dieren die in het water leven. Bij dit proces spelen een aantal gebeurtenissen een rol:
1 Aerobe bacteriën breken het organisch materiaal af.
2 Er dringt geen licht meer door in het water.
3 Er is geen fotosynthese mogelijk bij waterplanten die onder water groeien.
4 Er ontstaat een laag afgestorven materiaal op de bodem.$$, 'inline'),
  ('56f7af82-a3b7-4a74-93fd-5bb5a9ca51b6', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$kweek van eendenkroos in bakken (afbeelding 3)$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context6.png$$,
   $$Voor haar onderzoek kweekt Van der Meer eendenkroos in bakken, onder gecontroleerde omstandigheden (afbeelding 3).
afbeelding 3: foto van kweekbakken met eendenkroos in een kas$$, 'inline'),
  ('e4761507-e1a4-4fde-a1c8-348735aa3f6d', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$stikstof en vier organische stoffen$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context7.png$$,
   $$Het water in de bakken bevat onder andere anorganische stikstofverbindingen. De stikstof (N) is nodig voor de vorming van aminozuren en andere organische stoffen. Enkele organische stoffen zijn:
1 cellulose
2 chlorofyl
3 DNA
4 RNA$$, 'inline'),
  ('ec422f87-9e32-4755-b181-88abb7802918', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$verdubbeling van de biomassa; mineralen als beperkende factor$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context8.png$$,
   $$Onder gunstige omstandigheden kan de biomassa van eendenkroos in één dag verdubbelen. Het is belangrijk om de hoeveelheid mineralen in het water goed te doseren, zodat ze geen beperkende factor worden. Ook de concentraties van O₂ en CO₂ worden gemonitord.$$, 'inline'),
  ('0ddce280-7cb3-4893-942d-a5574b021f4b', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$energieverlies in de voedselketen$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context9.png$$,
   $$Eendenkroos wordt al enkele jaren als veevoer geteeld. Van der Meer onderzoekt of eendenkroos ook geschikt is voor menselijke consumptie, omdat eiwitten zo via de kortst mogelijke voedselketen bij de mens terechtkomen. Dat is gunstig, want bij elke schakel in de voedselketen gaat een groot deel van de energie uit organische stoffen verloren. Oorzaken van dit energieverlies zijn dat dode en niet-eetbare delen niet gegeten worden en dat een deel van de organische stoffen in ontlasting terechtkomt. Er is nog een belangrijke oorzaak van dit energieverlies.$$, 'inline'),
  ('27dfcbde-96a8-43d8-b131-a56176c2d3ca', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$kader: onderzoek naar de verteerbaarheid van eendenkroos$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context10.png$$,
   $$Door het hoge eiwitgehalte is eendenkroos mogelijk geschikt als vleesvervanger. De eiwitten moeten dan wel goed verteerbaar zijn en bepaalde aminozuren bevatten. Van der Meer onderzocht de verteerbaarheid van eendenkroos. De proefpersonen mochten een nacht en een ochtend niets eten, zodat het gehalte aan aminozuren in hun bloed laag werd. Daarna gaf ze de proefpersonen gekookt eendenkroos te eten. Voor en na het eten werd bij de proefpersonen bloed afgenomen. De bloedmonsters werden onderzocht op het gehalte aan essentiële aminozuren.$$, 'inline'),
  ('8424447f-0b75-4bd4-8272-8b77f9c899da', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$verticale landbouw (afbeelding 4)$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context11.png$$,
   $$Van der Meer ziet mogelijkheden om het hele jaar eendenkroos te kweken door middel van verticale landbouw. Bij verticale landbouw worden groenten onder gecontroleerde omstandigheden in meerdere lagen boven elkaar geteeld (afbeelding 4), bijvoorbeeld in leegstaande gebouwen.
afbeelding 4: ⚠️ CONTROLEREN: de afbeelding is in de bron-PDF leeg$$, 'inline'),
  ('23340a88-5554-4990-b839-e40744d1fc7c', '340276f1-e8d9-4ecd-aa09-188da6edeb9b', $$minder landbouwgrond door verticale landbouw$$,
   $$biologie-havo-2025-i-een-nieuwe-groente-eendenkroos-context12.png$$,
   $$Door verticale landbouw is er minder landbouwgrond nodig.$$, 'inline'),
  ('e3c2c618-83e7-4097-9fd5-ccc203f1caa9', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$inleiding: de Bajau, zeenomaden in Indonesië$$,
   $$biologie-havo-2025-i-de-bajau-context1.png$$,
   $$De Bajau (afbeelding 1) is een volk van zeenomaden in Indonesië. Ze zijn in staat om lang onder water te blijven zonder hulpmiddelen.$$, 'inline'),
  ('8769b70c-b3b4-4de7-a18b-372373764990', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$afbeelding 1: foto van de Bajau$$,
   $$biologie-havo-2025-i-de-bajau-context2.png$$,
   $$afbeelding 1: foto van paalwoningen en bootjes van de Bajau op zee$$, 'inline'),
  ('488820b8-0196-4632-96ac-c980067623ab', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$kader: duiken zonder duikuitrusting$$,
   $$biologie-havo-2025-i-de-bajau-context3.png$$,
   $$Veel Bajau-mannen vissen met behulp van een harpoen. Ze duiken hierbij zonder duikuitrusting tot wel 70 meter diep en kunnen tien minuten onder water blijven.$$, 'inline'),
  ('bb3074d4-3c5c-4675-af63-cb33fd9f3754', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$adem inhouden en drie uitspraken$$,
   $$biologie-havo-2025-i-de-bajau-context4.png$$,
   $$Om lang zijn adem in te kunnen houden, kan een duiker vooraf een aantal keer diep in- en uitademen. Dit vergroot de hoeveelheid zuurstof in het bloed niet, maar zorgt ervoor dat de ademprikkel later komt. De duiker kan hierdoor echter buiten bewustzijn raken voordat de ademprikkel ontstaat, en kan zo verdrinken. Hieronder staan drie uitspraken.
1 Door het inhouden van de adem wordt het restvolume van de longen groter.
2 De duiker raakt buiten bewustzijn, doordat de O₂-concentratie in zijn bloed te laag wordt.
3 De ademprikkel blijft uit, omdat de CO₂-concentratie in het bloed hoog is.$$, 'inline'),
  ('f01dce40-8235-4899-bfe0-250f9c7a8e5b', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$kader: milt en maximale duiktijd bij zeehonden$$,
   $$biologie-havo-2025-i-de-bajau-context5.png$$,
   $$Uit onderzoek bij zeehonden is bekend dat er een relatie is tussen de grootte van de milt en de maximale duiktijd. Bij zuurstoftekort kan de milt samentrekken om extra rode bloedcellen aan het bloed toe te voegen.$$, 'inline'),
  ('4f5d4130-000b-4710-b348-df76925b4361', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$zenuwstelsel en samentrekken van de milt$$,
   $$biologie-havo-2025-i-de-bajau-context6.png$$,
   $$Wetenschappers denken dat het samentrekken van de milt aan het begin van een duik, wordt veroorzaakt door signalen van het deel van het zenuwstelsel dat het lichaam gereedmaakt voor actie.$$, 'inline'),
  ('c014de94-891e-4d29-8fde-db921eb85c70', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$milt slaat rode bloedcellen op en breekt ze af$$,
   $$biologie-havo-2025-i-de-bajau-context7.png$$,
   $$De milt kan rode bloedcellen opslaan en speelt een rol bij de afbraak ervan.$$, 'inline'),
  ('85016c2d-62ec-4da6-a097-7d7ac32d53e4', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$afbraak van het zuurstoftransporterende eiwit$$,
   $$biologie-havo-2025-i-de-bajau-context8.png$$,
   $$Bij de afbraak van rode bloedcellen wordt ook het eiwit afgebroken dat zuurstof transporteert.$$, 'inline'),
  ('6613c79e-3f15-4220-93d0-391327e90001', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$kader: onderzoek naar DNA en miltgrootte van Bajau en Saluan$$,
   $$biologie-havo-2025-i-de-bajau-context9.png$$,
   $$Deense onderzoekers vroegen zich af of de uitzonderlijke duikcapaciteit van de Bajau ook een relatie heeft met de grootte van hun milt en of deze aanpassing een genetische basis heeft. Hiervoor onderzochten ze het DNA en de grootte van de milt van 59 Bajau-mannen en van 34 Saluan- mannen. De Saluan leven van akkerbouw en veeteelt in dezelfde regio. De onderzoekers isoleerden het DNA uit cellen van het wangslijmvlies. Met behulp van echografie bepaalden ze de grootte van de milt.$$, 'inline'),
  ('7e373066-a89d-45e7-8cc4-37629841ce38', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$DNA uit cellen van het wangslijmvlies$$,
   $$biologie-havo-2025-i-de-bajau-context10.png$$,
   $$Cellen van de milt zijn moeilijk af te nemen. Dat was ook niet nodig, de onderzoekers isoleerden DNA uit cellen van het wangslijmvlies.$$, 'inline'),
  ('41c1690b-7656-45aa-a01e-ac0bd1b8f3d9', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$milt en echografie$$,
   $$biologie-havo-2025-i-de-bajau-context11.png$$,
   $$De milt is onderdeel van het lymfevatenstelsel. Met echografie werd de grootte van de milt bepaald. De transductor (afbeelding 2) van het echoapparaat wordt op de plaats op de romp gezet waar zich de milt bevindt. Op een beeldscherm kan de milt dan zichtbaar worden gemaakt.$$, 'inline'),
  ('6e073250-4207-455e-9fdb-bb2fbf3318df', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$afbeelding 2 en 3: echografie en romp met plaatsen P-T$$,
   $$biologie-havo-2025-i-de-bajau-context12.png$$,
   $$afbeelding 2: foto van een echografie met de transductor op de romp
afbeelding 3: tekening van de romp van voren met vijf plaatsen: P en Q hoog links en rechts, R en S lager links en rechts, T onderin het midden$$, 'inline'),
  ('787748f4-9553-4d89-b706-53771c936a92', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$miltgrootte erfelijk of door duiken; vervolgonderzoek$$,
   $$biologie-havo-2025-i-de-bajau-context13.png$$,
   $$Uit het onderzoek blijkt dat de milt bij de Bajau-mannen gemiddeld groter is dan bij de Saluan-mannen. Uit dit onderzoek is niet af te leiden of een grotere milt erfelijk is, of dat individuen een grotere milt ontwikkelen tijdens hun leven door het vele duiken. Om dat te bepalen, moet in een vervolgonderzoek de miltgrootte van twee andere groepen met elkaar vergeleken worden.$$, 'inline'),
  ('7e0f006b-d261-4c77-98c1-251939b5cb09', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$kader: mutatie op chromosoom 6 en miltgrootte (afbeelding 4)$$,
   $$biologie-havo-2025-i-de-bajau-context14.png$$,
   $$Na de analyse van het DNA vonden onderzoekers in een gen op chromosoom 6 een mutatie die samenhangt met de grootte van de milt. Afbeelding 4 laat de relatie zien tussen het genotype (aantal mutante allelen van dit gen) en het fenotype (de miltgrootte bij Bajau-mannen).
afbeelding 4: staafdiagram fenotype (gemiddelde grootte van de milt in cm³) tegen genotype (aantal mutante allelen): 0 allelen ongeveer 135 cm³, 1 allel ongeveer 220 cm³, 2 allelen ongeveer 330 cm³$$, 'inline'),
  ('0a2c9994-8231-48dc-9a6a-f49dbfdacf84', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$drie uitspraken over het informatiekader$$,
   $$biologie-havo-2025-i-de-bajau-context15.png$$,
   $$Hieronder staan uitspraken over de gegevens in het informatiekader.
1 Het mutante allel erft autosomaal over.
2 Mensen met één keer het mutante allel hebben een intermediair fenotype.
3 De grootte van de milt wordt alleen bepaald door het gen op chromosoom 6.$$, 'inline'),
  ('9f2ab0c8-8bb6-45b9-a7fa-7ddc9a660ece', 'ecb62a3b-d239-400a-b348-17962cae8ff5', $$grotere milt als gevolg van evolutie$$,
   $$biologie-havo-2025-i-de-bajau-context16.png$$,
   $$De onderzoekers vermoeden dat de grotere milt van de Bajau-mannen het gevolg is van evolutie.$$, 'inline'),
  ('8c12e011-2b47-4255-a659-adc784297556', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$inleiding: Jasper en een resistente schimmel$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context1.png$$,
   $$Jasper heeft een levensgevaarlijke infectie gehad met een schimmel die resistent is tegen medicijnen. Deze schimmel is waarschijnlijk resistent geworden door het gebruik van schimmelbestrijdingsmiddelen in de akkerbouw.$$, 'inline'),
  ('d0efa296-a624-40ed-ad04-55fd57554df2', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$kader: Aspergillus fumigatus en aspergillose (afbeelding 1)$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context2.png$$,
   $$Aspergillus fumigatus is een schimmel die algemeen aanwezig is in de bodem. Je ademt dagelijks sporen van deze schimmel in (afbeelding 1). Bij gezonde mensen ruimt het immuunsysteem de sporen op. Als gevolg van een ziekte heeft Jasper echter een sterk verlaagde weerstand, waardoor de schimmel een gevaarlijke infectie veroorzaakte. Dit wordt aspergillose genoemd.
afbeelding 1: schimmel op de bodem (schaal 10 µm) die sporen afgeeft; de sporen worden ingeademd en veroorzaken aspergillose in de longen$$, 'inline'),
  ('8471931b-833c-41bd-ad0f-8c462420d405', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$slijmcellen en trilhaarcellen in de luchtwegen$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context3.png$$,
   $$De meeste sporen komen niet verder dan de luchtpijp en de bronchiën doordat deze delen van de luchtwegen dekweefsel bezitten met slijmcellen en trilhaarcellen.$$, 'inline'),
  ('78b41c58-80ef-4872-b42c-bcd2a68656b3', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$kader: schimmelcellen in het hersenweefsel$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context4.png$$,
   $$Jasper kreeg antischimmel-medicijnen. Toch liet hij korte tijd daarna steeds dingen uit zijn handen vallen en kreeg hij moeite met lopen. Dat was voor Jaspers arts de aanleiding om een hersenscan te laten maken. Op de hersenscan waren enkele verdachte plekken te zien. Daarom nam een neurochirurg hersenweefsel af en bekeek het met een microscoop. Haar vermoeden werd bevestigd: er waren schimmelcellen aanwezig in het hersenweefsel. De medicijnen hadden blijkbaar niet gewerkt.$$, 'inline'),
  ('9e90aadf-18d8-42b3-bab9-f92d5bed9200', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$vier onderdelen van cellen$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context5.png$$,
   $$Hieronder staan enkele onderdelen van cellen.
1 bladgroenkorrels
2 celkern
3 celwand
4 vacuole$$, 'inline'),
  ('30d0731e-81d8-4d0b-9067-17730956a9c1', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$hersenscans van Jaspers grote hersenen$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context6.png$$,
   $$In afbeelding 2 zijn tekeningen van de hersenscans van Jaspers grote hersenen te zien. Het zijn verschillende doorsnedes. De bovenzijde van elke tekening is de voorkant van zijn hoofd. De pijlen wijzen plaatsen aan waar zenuwcellen vernietigd zijn door de schimmel.$$, 'inline'),
  ('4ad7beec-432b-48fe-8d43-0093fdc09bcc', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$afbeelding 2: tekeningen van drie hersenscans$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context7.png$$,
   $$afbeelding 2: drie tekeningen (1, 2 en 3) van doorsnedes van de grote hersenen, met op elke tekening een pijl naar een plaats waar zenuwcellen vernietigd zijn (bovenzijde = voorkant van het hoofd)$$, 'inline'),
  ('cef61878-013f-44d9-bff6-0ac41b8bce03', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$schimmel in het gebied dat de rechterhand aanstuurt$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context8.png$$,
   $$Op een van de tekeningen in afbeelding 2 is te zien dat de schimmel het gebied heeft geïnfecteerd dat Jaspers rechterhand aanstuurt.$$, 'inline'),
  ('0d2e7aac-c29a-48a6-b236-dabb550a9bc7', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$kader: azolen remmen lanosteroldemethylase$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context9.png$$,
   $$De antischimmelmedicijnen die Jasper kreeg, waren azolen. Azolen remmen de werking van het enzym lanosteroldemethylase. Dit enzym is nodig voor de productie van ergosterol. Ergosterol is een bestanddeel van de celmembraan van schimmels.$$, 'inline'),
  ('1d070df5-2b0e-4fbf-9926-09a7a3903595', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$op de uitwerkbijlage staat een schema$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context10.png$$,
   $$Op de uitwerkbijlage staat een schema.$$, 'inline'),
  ('32d01673-399b-4b9c-9d0b-2c52049af687', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$puntmutatie: codon voor leucine wordt histidine$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context11.png$$,
   $$De schimmel in de longen en hersenen van Jasper bleek resistent tegen azolen door een puntmutatie in het gen voor het enzym lanosteroldemethylase. Het codon voor het aminozuur leucine is gewijzigd in een codon voor het aminozuur histidine. Daardoor heeft het enzym een iets andere vorm, met als gevolg dat azolen dit enzym niet meer kunnen remmen. Ondanks de andere vorm is het enzym nog wel werkzaam.$$, 'inline'),
  ('73af8616-6c2e-4b06-9f6f-3f9f3c3396e5', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$resistente schimmel bij meerdere patiënten$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context12.png$$,
   $$Resistentie van een schimmel tegen een medicijn kan ontstaan na herhaald gebruik van dit medicijn. Jasper was echter nog niet eerder behandeld met azolen. Ook bij andere aspergillose-patiënten komt de resistente Aspergillus fumigatus met dezelfde puntmutatie voor. De overdracht van sporen tussen mensen is niet mogelijk. Artsen vermoeden daarom dat de patiënten de ziekte oplopen door het inademen van resistente schimmelsporen uit het milieu.$$, 'inline'),
  ('91a70b3b-aeff-45f1-97e9-0f971bc4eeae', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$kader: azolen in de akkerbouw en composthopen$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context13.png$$,
   $$In de akkerbouw worden azolen gebruikt om voedselgewassen en bloembollen te beschermen tegen schimmelinfecties. Deze azolen komen met plantenafval terecht op composthopen. Waarschijnlijk is in zo’n composthoop de resistente Aspergillus fumigatus ontstaan.$$, 'inline'),
  ('3058dad9-1b4b-4e33-98c2-a53fd36241b5', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$A. fumigatus in de kringloop van stoffen$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context14.png$$,
   $$A. fumigatus komt veel voor in composthopen, en speelt een rol in de kringloop van stoffen.$$, 'inline'),
  ('6523efbb-6f1a-45ed-968c-7d32ad34a082', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$A. fumigatus scheidt amylase uit$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context15.png$$,
   $$A. fumigatus scheidt amylase uit. Amylase is een enzym dat bepaalde moleculen uit het plantaardig afval afbreekt tot voedingsstoffen die door de schimmel kunnen worden opgenomen.$$, 'inline'),
  ('6379656b-5f24-4c21-bfc2-e02a400bd8a9', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$nierschade en kaliumtekort$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context16.png$$,
   $$Jasper kreeg andere medicijnen toegediend die wel goed werkten tegen de schimmel, waardoor hij herstelde. Maar door de hoge dosering van de medicijnen liepen Jaspers nieren schade op. Als gevolg hiervan heeft Jasper onder andere een grotere kans op een kaliumtekort.$$, 'inline'),
  ('00b822a0-9e16-4396-830c-4804b6b65114', '12c53dc4-ad4b-43cc-a67f-5441db412912', $$uitwerkbijlage vraag 38: schema ergosterolproductie$$,
   $$biologie-havo-2025-i-gevaarlijke-sporen-context17.png$$,
   $$38
uitwerkbijlage: schema met lanosterol → ......; daarboven twee lege invulplaatsen, elk met een pijl en een lege cirkel naar de pijl eronder$$, 'uitwerkbijlage'),
  ('8839bbbb-7812-41f7-aefd-5a4b096e01df', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$inleiding: umami-smaakstoffen in eieren en spek versterken elkaar$$,
   $$biologie-havo-2025-i-eieren-met-spek-context1.png$$,
   $$Veel mensen vinden de combinatie van eieren met spek lekker. Uit onderzoek blijkt dat dat komt doordat verschillende umami-smaakstoffen in deze voedingsmiddelen elkaar versterken.$$, 'inline'),
  ('c9033506-70c2-4dca-9cd1-42098494741e', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$kader: umami en smaakzintuigcellen$$,
   $$biologie-havo-2025-i-eieren-met-spek-context2.png$$,
   $$Umami (hartig) is de vijfde smaak die mensen kunnen onderscheiden. Elk van de vijf smaken in voedsel veroorzaakt een reactie in specifieke smaakzintuigcellen op de tong.$$, 'inline'),
  ('12cfe6b2-5e00-4718-8924-184e212eb1e0', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$smaak wordt waargenomen in de hersenen$$,
   $$biologie-havo-2025-i-eieren-met-spek-context3.png$$,
   $$Reacties in de smaakzintuigcel leiden ertoe dat de smaak uiteindelijk wordt waargenomen in de hersenen.$$, 'inline'),
  ('435d0044-41ec-47c4-8435-3ed89bc6a3b3', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$afbeelding 1: umami-smaakstof, smaakzintuigcel en zenuwcel$$,
   $$biologie-havo-2025-i-eieren-met-spek-context4.png$$,
   $$Afbeelding 1 laat zien hoe binding van umami-smaakstof aan een receptor op een smaakzintuigcel op de tong leidt tot een signaal in een zenuwcel. In de tekst hieronder staan de verschillende stappen in het proces. Op drie plaatsen ontbreekt een woord.
afbeelding 1: tekening van smaakzintuigcellen met umami-smaakstof die aan receptoren bindt, blaasjes in de smaakzintuigcel en een uitloper van een sensorische zenuwcel$$, 'inline'),
  ('d4aa36f0-7834-41ee-ba54-3a46d9519695', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$tekst met drie ontbrekende woorden$$,
   $$biologie-havo-2025-i-eieren-met-spek-context5.png$$,
   $$Umami-smaakstoffen binden aan receptoren op de smaakzintuigcel. Na een keten van reacties worden blaasjes met ...(1)... richting het membraan getransporteerd. De inhoud van de blaasjes komt door ...(2)... in de synaps tussen de smaakzintuigcel en de zenuwcel terecht. Dit leidt tot het ontstaan van ...(3)... in de zenuwcel.$$, 'inline'),
  ('2c8c065d-e1a7-4fab-839d-5c8655be3d80', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$kader: onderzoek van Schmidt (regels 1-13)$$,
   $$biologie-havo-2025-i-eieren-met-spek-context6.png$$,
   $$1 Onderzoeker Charlotte Schmidt veronderstelde dat bepaalde
2 voedselcombinaties lekker worden gevonden doordat umami-
3 smaakstoffen uit beide producten elkaar versterken.
4 Uit eerder onderzoek bleek dat bij eieren de umami-smaak vooral wordt
5 veroorzaakt door het aminozuur glutaminezuur.
6 Bij spek wordt de umami-smaak veroorzaakt door bepaalde nucleotiden.
7 Schmidt ontdekte dat wanneer deze nucleotiden aanwezig zijn,
8 glutaminezuur sterker wordt gebonden aan de receptor.
9 Dit leidt tot een sterker signaal naar de hersenen, zodat de umami-smaak
10 sterker wordt waargenomen.
11 Schmidt leidde hieruit af dat twee umami-smaakstoffen waarvan de één
12 een nucleotide is en de ander een aminozuur, elkaar inderdaad kunnen
13 versterken.$$, 'inline'),
  ('802106d1-81cc-4ac7-a210-7c916d2c3ef7', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$kader: profielwerkstuk met drie puddingen$$,
   $$biologie-havo-2025-i-eieren-met-spek-context7.png$$,
   $$Han en Kees willen voor hun profielwerkstuk onderzoeken of de smaakstoffen van ham en van kaas elkaar op dezelfde manier versterken als spek en eieren. Ze maken drie puddingen waaraan ze verschillende smaakstoffen toevoegen: Pudding 1: ham-smaakstof, in een concentratie net onder de drempelwaarde. Pudding 2: kaas-smaakstof, in een concentratie net onder de drempelwaarde. Pudding 3: beide smaakstoffen, met dezelfde concentratie ham-smaakstof als in pudding 1 en dezelfde concentratie kaas-smaakstof als in pudding 2.
50 leerlingen doen mee aan het onderzoek. Deze proefpersonen proeven elke pudding door er een even grote hap van te nemen. Kees noteert of de proefpersonen wel of niet ham en/of kaas waarnemen. Na elke hap spoelen de proefpersonen hun mond met water.$$, 'inline'),
  ('c8a19794-64d4-461d-9f6b-6a2b47017ef6', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$op de uitwerkbijlage staat een tabel$$,
   $$biologie-havo-2025-i-eieren-met-spek-context8.png$$,
   $$Op de uitwerkbijlage staat een tabel.$$, 'inline'),
  ('1ff808bc-25de-4c0c-9b9a-0fea790232a5', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$controle: extra puddingen$$,
   $$biologie-havo-2025-i-eieren-met-spek-context9.png$$,
   $$Om te controleren of de proefpersonen wel in staat zijn om ham- en kaassmaak waar te nemen, laten Han en Kees hun proefpersonen op dezelfde manier extra puddingen proeven.$$, 'inline'),
  ('f7abb84a-a0c6-4ddf-90ae-343f4300e049', '135906f8-8089-4aab-ac58-cc80d1e5386d', $$uitwerkbijlage vraag 47: tabel smaakwaarneming per pudding$$,
   $$biologie-havo-2025-i-eieren-met-spek-context10.png$$,
   $$47
uitwerkbijlage: tabel met kolommen wel smaakwaarneming / geen smaakwaarneming en rijen pudding 1, pudding 2, pudding 3$$, 'uitwerkbijlage');

