   '[{"domain": "Zelfregulatie", "subdomain": "Regulatie van ecosystemen"}]'::jsonb,
   '["natuurbeheer", "biodiversiteit", "beschermde soort", "populatiegrootte", "argumenteren"]'::jsonb,
