   $$biologie-havo-2025-i-de-zeearend-moet-blijven-vraag9.png$$, $$1p 9 Noteer een biologisch argument dat zijn standpunt ondersteunt.$$, array['01842a16-db25-497a-944a-dcab5b327495', '3e597fae-7e48-44b7-9254-edaf0a1caec0']::uuid[]),
